/*
 * The interface's live connection, over server-sent events.
 *
 * The interface itself is unchanged: it still calls io(), still binds handlers with .on()
 * and still sends operations with .emit(). What changed is underneath -- the connection is
 * an event stream and an ordinary request rather than a bidirectional socket, which is the
 * one part of a reused front end this rebuild is meant to replace.
 *
 * Two things this has to get right that a socket gave for free:
 *
 *  - A dropped connection has to be visible. The stream reconnects by itself, but a page
 *    that silently shows stale rows while disconnected looks exactly like a working one, so
 *    a drop fires the interface's own disconnect handler and a reconnect fires its connect
 *    handler -- which is what shows and hides the warning the page already has.
 *
 *  - Nothing is missed across a gap. The stream carries a position, the client sends back
 *    the last one it saw, and the server replays from there, so an operation that finished
 *    while the page was disconnected still arrives.
 */
(function (global) {
  "use strict";

  function Connection(options) {
    var self = this;
    this.handlers = {};
    this.path = (options && options.path) || "/socket.io";
    this.lastEventId = null;
    this.closed = false;
    this.source = null;
    this.connected = false;
    this.reconnectDelay = (options && options.reconnectionDelay) || 3000;

    // Shaped like the object the interface reads for its own logging.
    this.io = { engine: { transport: { name: "server-sent-events" } } };

    this.open();
  }

  Connection.prototype.open = function () {
    var self = this;
    if (this.closed) {
      return;
    }
    var url = this.path + "/stream";
    if (this.lastEventId) {
      url += "?since=" + encodeURIComponent(this.lastEventId);
    }

    try {
      this.source = new EventSource(url);
    } catch (e) {
      this.scheduleReopen();
      return;
    }

    this.source.onopen = function () {
      if (!self.connected) {
        self.connected = true;
        self.dispatch("connect", {});
      }
    };

    this.source.onmessage = function (message) {
      if (message.lastEventId) {
        self.lastEventId = message.lastEventId;
      }
      var frame;
      try {
        frame = JSON.parse(message.data);
      } catch (e) {
        return;
      }
      if (!frame || !frame.event) {
        return;
      }
      if (frame.event === "keepalive") {
        return;
      }
      self.dispatch(frame.event, frame.data || {});
    };

    this.source.onerror = function () {
      if (self.connected) {
        self.connected = false;
        self.dispatch("disconnect", "transport error");
      }
      if (self.source) {
        self.source.close();
        self.source = null;
      }
      self.scheduleReopen();
    };
  };

  Connection.prototype.scheduleReopen = function () {
    var self = this;
    if (this.closed) {
      return;
    }
    setTimeout(function () {
      self.open();
    }, this.reconnectDelay);
  };

  Connection.prototype.dispatch = function (event, data) {
    var listeners = this.handlers[event];
    if (!listeners) {
      return;
    }
    for (var i = 0; i < listeners.length; i++) {
      try {
        listeners[i](data);
      } catch (e) {
        console.error("handler for '" + event + "' failed", e);
      }
    }
  };

  Connection.prototype.on = function (event, handler) {
    if (!this.handlers[event]) {
      this.handlers[event] = [];
    }
    this.handlers[event].push(handler);
    if (event === "connect" && this.connected) {
      handler({});
    }
    return this;
  };

  Connection.prototype.off = function (event) {
    delete this.handlers[event];
    return this;
  };

  Connection.prototype.emit = function (event, payload) {
    var self = this;
    var headers = { "Content-Type": "application/json" };
    if (typeof csrftoken !== "undefined" && csrftoken) {
      headers["X-CSRFToken"] = csrftoken;
    }
    fetch(this.path + "/emit/" + encodeURIComponent(event), {
      method: "POST",
      headers: headers,
      body: JSON.stringify(payload || {})
    })
      .then(function (response) {
        return response.json().catch(function () {
          return {};
        });
      })
      .then(function (body) {
        if (body && body.event) {
          self.dispatch(body.event, body.data || {});
        }
      })
      .catch(function (error) {
        console.error("operation '" + event + "' failed", error);
      });
    return this;
  };

  Connection.prototype.disconnect = function () {
    this.closed = true;
    if (this.source) {
      this.source.close();
      this.source = null;
    }
    return this;
  };

  global.io = function (options) {
    return new Connection(options);
  };
})(window);
